INSERT OR REPLACE INTO clothing (id, name, short_description, long_description, clothing_type, locations_covered, effect_text, cost, weight) VALUES (22, 'Alchemist''s Attire', '', '', 'Outfit', 'Arm, Leg, Torso', '', 28.0, 1.0);
